const searchResults = items;
const campaignData = $('Loop Over Items').item.json;

let targetRow = 0;

if (searchResults && searchResults.length > 0 && searchResults[0].json && searchResults[0].json.row_number) {
    for (const row of searchResults) {
        // Bỏ qua 5 hàng đầu tiên (tiêu đề, tổng tiền...)
        if (row.json.row_number < 6) continue;

        let colBValue = "";

        // Thử lấy cột B theo tên chuẩn (nếu N8N đọc đúng hàng 3)
        if (row.json['TÊN CAMP'] !== undefined) {
            colBValue = row.json['TÊN CAMP'] ? row.json['TÊN CAMP'].toString().trim() : "";
        } else {
            // Nếu N8N đọc nhầm hàng 1 làm tiêu đề, cột B sẽ mang tên Sale (VD: 'Linh', 'Toàn')
            // Ta sẽ lấy key thứ 2 trong object (sau 'Sale' hoặc 'STT')
            const keys = Object.keys(row.json).filter(k => k !== 'row_number' && k !== 'Sale' && k !== 'STT');
            if (keys.length > 0) {
                const colBKey = keys[0];
                colBValue = row.json[colBKey] ? row.json[colBKey].toString().trim() : "";
            }
        }

        // Nếu cột B trống, đây chính là hàng trống đầu tiên (hàng cuối cùng chờ điền)
        if (colBValue === "") {
            targetRow = row.json.row_number;
            break; // Tìm thấy thì dừng lại ngay để ghi vào hàng này
        }
    }
}

return [{
    json: {
        ...campaignData,
        row_number: targetRow 
    }
}];

