// 3. Duyệt từng chiến dịch
for (const camp of campaigns) {
    const insightData = (camp.insights && camp.insights.data && camp.insights.data[0]) ? camp.insights.data[0] : {};

    const actions = insightData.actions || [];
    const spend = parseFloat(insightData.spend || 0);

    const msgAction = actions.find(a => 
      a.action_type === 'onsite_conversion.messaging_conversation_started_7d' || 
      a.action_type === 'onsite_conversion.total_messaging_connection'
    );
    const messages = msgAction ? parseInt(msgAction.value) : 0;

    let statusVN = 'TẮT';
    if (camp.effective_status === 'ACTIVE') {
        statusVN = 'HOẠT ĐỘNG';
    }

    // Lọc: Có tên và có tiêu tiền
    if (camp.name && spend > 0) {
        const sheetName = getSheetName(camp.name);
        if (sheetName) {
            results.push({
                json: {
                    campaign_name: camp.name,
                    spend: spend,
                    messages: messages,
                    status: statusVN,
                    date: reportDate,
                    sheet_name: sheetName
                }
            });
        }
    }
}

return results;
